import { Storage } from './storage';
import { updateAllWidgets } from './widgetUpdater';

/**
 * Where Aura's generated day plan lives locally.
 *
 * The plan is deliberately a LOCAL, per-day artifact: it is regenerated by Aura
 * rather than being a source of truth, so it lives in AsyncStorage keyed by user
 * and stamped with the day it was built for. Anything reading it must check the
 * date stamp — a plan from yesterday is not today's plan.
 */
export const planKey = (userId) => `generated_plan_${userId}`;
export const planDateKey = (userId) => `generated_plan_date_${userId}`;

/**
 * Persist the plan for TODAY and push it to the home-screen Planner widget.
 *
 * Used by every screen that hosts the Aura overlay so the save behaviour (and
 * the widget refresh) can't drift between them.
 */
export async function savePlanForToday(userId, plan) {
  if (!userId) return;
  try {
    await Storage.set(planKey(userId), plan);
    await Storage.set(planDateKey(userId), new Date().toDateString());
  } catch (error) {
    console.warn('[PlanStore] Failed to save plan:', error?.message || error);
    return;
  }
  // Fire-and-forget: the widget is a mirror, so a failed refresh must never
  // block or break the in-app save.
  updateAllWidgets().catch(() => {});
}

/**
 * Turn a plan into shareable plain text (used by the Share button in Aura).
 * Kept here so the widget, the overlay and any future export agree on format.
 */
export function formatPlanAsText(plan, { heading = "Today's Plan" } = {}) {
  const items = Array.isArray(plan) ? plan.filter((i) => i && i.title) : [];
  if (items.length === 0) return '';

  const date = new Date().toLocaleDateString(undefined, {
    weekday: 'long',
    month: 'short',
    day: 'numeric',
  });

  const lines = items.map((item) => {
    const time = String(item.time || '').trim();
    const mark = item.completed ? '[x]' : '[ ]';
    return time ? `${time}  ${mark} ${item.title}` : `${mark} ${item.title}`;
  });

  return `${heading} · ${date}\n\n${lines.join('\n')}\n\n— planned with LifePilot`;
}
